// STANDARDIZED ACTIVITY LOGGING FUNCTION
// ============================================
/**
 * Logs an activity with consistent user identification
 * @param {string} action - Description of the action performed
 * @returns {Promise<void>}
 */
window.logActivity = async (action) => {
    try {
        // Use fullName if available, fallback to username, then to 'System'
        const userName = currentUser?.fullName || currentUser?.username || 'System';

        await addDoc(collection(db, 'activities'), {
            action: action,
            user: userName,
            date: new Date().toISOString()
        });

        // Update local activities array
        activities.unshift({
            action: action,
            user: userName,
            date: new Date().toISOString()
        });

        // Keep only last 100 activities in memory
        if (activities.length > 100) {
            activities = activities.slice(0, 100);
        }
    } catch (error) {
        console.error('Error logging activity:', error);
        // Don't throw - activity logging shouldn't break main functionality
    }
};

