window.addEventListener('load', () => {
    checkSession();
});

function checkSession() {
    try {
        const savedSession = localStorage.getItem(SESSION_KEY);
        if (savedSession) {
            const sessionData = JSON.parse(savedSession);
            if (sessionData && sessionData.user) {
                currentUser = sessionData.user;
                window.currentUser = currentUser; // Expose to global scope
                showMainApp();
                loadData();
                // Start status sync for technicians
                if (currentUser.role === 'technician') {
                    setTimeout(() => startStatusSync(), 2000);
                }
            }
        }
    } catch (error) {
        console.error('Error restoring session:', error);
        localStorage.removeItem(SESSION_KEY);
    }
}

function saveSession(user) {
    try {
        const sessionData = {
            user: user,
            timestamp: new Date().toISOString()
        };
        localStorage.setItem(SESSION_KEY, JSON.stringify(sessionData));
    } catch (error) {
        console.error('Error saving session:', error);
    }
}

function clearSession() {
    localStorage.removeItem(SESSION_KEY);
}

document.getElementById('loginForm').addEventListener('submit', async (e) => {
    e.preventDefault();
    const username = document.getElementById('username').value.trim();
    const password = document.getElementById('password').value;
    const loginBtn = document.getElementById('loginBtn');
    const loginError = document.getElementById('loginError');

    if (loginBtn) {
        loginBtn.disabled = true;
        loginBtn.textContent = 'Signing in...';
    }
    if (loginError) {
        loginError.style.display = 'none';
    }

    try {
        if (!username || !password) {
            throw new Error('Please enter both username and password');
        }
        
        if (username === ADMIN_USERNAME && password === ADMIN_PASSWORD) {
            currentUser = {
                id: 'admin',
                username: ADMIN_USERNAME,
                fullName: 'Administrator',
                role: 'admin',
                status: 'active'
            };
            window.currentUser = currentUser; // Expose to global scope
            saveSession(currentUser);
            showMainApp();
            await loadData();
            return;
        }

        if (isOnline) {
            let foundUser = null;
            
            // Normalize username for case-insensitive comparison
            const normalizedUsername = username.toLowerCase();
            
            // First check the 'users' collection
            console.log('=== Checking users collection ===');
            const usersSnapshot = await getDocs(collection(db, 'users'));
            console.log('Users found:', usersSnapshot.size);
            usersSnapshot.forEach(doc => {
                const userData = doc.data();
                if (userData.username && userData.username.toLowerCase() === normalizedUsername && userData.password === password) {
                    console.log('✅ Found matching user:', userData.username);
                    foundUser = { id: doc.id, ...userData };
                }
            });
            
            // If not found in users, check the 'employees' collection (HR portal creates employees here)
            if (!foundUser) {
                console.log('=== Checking employees collection ===');
                const employeesSnapshot = await getDocs(collection(db, 'employees'));
                console.log('Employees found:', employeesSnapshot.size);
                employeesSnapshot.forEach(doc => {
                    const empData = doc.data();
                    console.log('Checking employee:', empData.username, 'Status:', empData.systemStatus);
                    if (empData.username && empData.username.toLowerCase() === normalizedUsername && empData.password === password) {
                        console.log('✅ Found matching employee:', empData.username);
                        // Map employee fields to user format for compatibility
                        foundUser = {
                            id: doc.id,
                            username: empData.username,
                            password: empData.password,
                            fullName: `${empData.firstName || ''} ${empData.lastName || ''}`.trim() || empData.username,
                            role: empData.systemRole || empData.role || 'user',
                            status: empData.systemStatus || empData.status || 'active'
                        };
                        console.log('Mapped employee to user format:', foundUser);
                    }
                });
            }

            if (foundUser) {
                console.log('Found user/employee:', foundUser.username, 'Status:', foundUser.status);
            } else {
                console.log('❌ No matching user/employee found');
            }

            if (foundUser && (foundUser.status === 'active' || foundUser.status === 'Active')) {
                console.log('✅ Login successful for:', foundUser.username);
                currentUser = foundUser;
                window.currentUser = currentUser; // Expose to global scope
                saveSession(currentUser);
                showMainApp();
                await loadData();
                // Start status sync for technicians
                if (currentUser.role === 'technician') {
                    setTimeout(() => startStatusSync(), 2000);
                }
            } else if (foundUser && foundUser.status !== 'active' && foundUser.status !== 'Active' && foundUser.status) {
                console.log('❌ Account inactive:', foundUser.status);
                throw new Error(`Account status is "${foundUser.status}". Please contact administrator.`);
            } else if (foundUser) {
                // Found user but no status or undefined status - treat as active
                console.log('⚠️ User found with no status, treating as active');
                currentUser = foundUser;
                window.currentUser = currentUser; // Expose to global scope
                saveSession(currentUser);
                showMainApp();
                await loadData();
                // Start status sync for technicians
                if (currentUser.role === 'technician') {
                    setTimeout(() => startStatusSync(), 2000);
                }
            } else {
                console.log('❌ Invalid credentials');
                throw new Error('Invalid username or password');
            }
        } else {
            throw new Error('Cannot login in offline mode. Please check your internet connection.');
        }
    } catch (error) {
        const loginError = document.getElementById('loginError');
        if (loginError) {
            loginError.textContent = error.message;
            loginError.style.display = 'block';
        }
        const loginBtn = document.getElementById('loginBtn');
        if (loginBtn) {
            loginBtn.disabled = false;
            loginBtn.textContent = 'Sign In';
        }
    }
});

function showMainApp() {
    document.getElementById('loginScreen').classList.add('hidden');
    document.getElementById('mainApp').classList.add('active');
    document.getElementById('userName').textContent = currentUser.fullName || currentUser.username;
    document.getElementById('userRole').textContent = currentUser.role.toUpperCase();
    
    // Apply translations
    applyTranslationsOnLogin();
    
    // ========== COMPREHENSIVE ROLE-BASED ACCESS CONTROL ==========
    const userRole = currentUser.role;

    // Define which tabs each role can see
    const rolePermissions = {
        admin: {
            tabs: ['dashboard', 'warehouse', 'service-van', 'office', 'projects', 'repairs', 'complaints', 'installation', 'modernisation', 'amc', 'tasks', 'tracking', 'billing', 'sales', 'activities', 'hr', 'leave', 'vendors', 'bom', 'settings'],
            canDelete: true,
            canCreateTasks: true,
            dashboardType: 'admin',
            dataAccess: 'full' // Full access to all data
        },
        sales: {
            tabs: ['dashboard', 'sales', 'projects', 'amc', 'billing', 'tasks', 'complaints', 'settings'],
            canDelete: false,
            canCreateTasks: true,
            dashboardType: 'sales',
            dataAccess: 'own' // Only created/assigned to self
        },
        technician: {
            tabs: ['dashboard', 'tasks', 'installation', 'modernisation', 'repairs', 'complaints', 'amc', 'tracking', 'service-van', 'leave', 'settings'],
            canDelete: false,
            canCreateTasks: false,
            dashboardType: 'technician',
            dataAccess: 'assigned' // Only assigned jobs and stock
        },
        reception: {
            tabs: ['dashboard', 'complaints', 'tasks', 'projects', 'settings'],
            canDelete: false,
            canCreateTasks: true,
            dashboardType: 'reception',
            dataAccess: 'complaints' // Complaint and routing only
        },
        user: {
            tabs: ['dashboard', 'projects', 'tasks', 'office', 'leave', 'settings'],
            canDelete: false,
            canCreateTasks: false,
            dashboardType: 'user',
            dataAccess: 'assigned' // Assigned internal data only
        }
    };

    const permissions = rolePermissions[userRole] || rolePermissions.user;

    // Hide ALL tabs first
    const allTabButtons = document.querySelectorAll('.nav-item');
    allTabButtons.forEach(btn => {
        btn.style.display = 'none';
    });

    // Show only allowed tabs
    const tabMapping = {
        'dashboard': null,  // No specific button ID
        'warehouse': null,
        'service-van': null,
        'office': null,
        'projects': null,
        'maintenance': null,
        'amc': null,
        'tasks': null,
        'tracking': 'trackingTabBtn',
        'billing': 'billingTabBtn',
        'sales': 'salesTabBtn',
        'activities': null,
        'hr': 'usersTabBtn',
        'leave': 'leaveTabBtn',
        'vendors': 'vendorsTabBtn',
        'bom': null,
        'settings': 'settingsTabBtn'
    };

    permissions.tabs.forEach(tab => {
        const btnId = tabMapping[tab];
        if (btnId) {
            const btn = document.getElementById(btnId);
            if (btn) btn.style.display = 'flex';
        } else {
            // Find button by onclick attribute
            allTabButtons.forEach(btn => {
                const onclick = btn.getAttribute('onclick');
                if (onclick && onclick.includes(`'${tab}'`)) {
                    btn.style.display = 'flex';
                }
            });
        }
    });

    // Set task creation permission
    const createTaskBtn = document.getElementById('createTaskBtn');
    if (createTaskBtn) {
        createTaskBtn.style.display = permissions.canCreateTasks ? 'block' : 'none';
    }

    // Hide add buttons for technicians
    if (userRole === 'technician') {
        const addButtonIds = [
            'addAMCBtn', 'addRepairBtn', 'addComplaintBtn',
            'addInstallationBtn', 'addModernisationBtn', 'addServiceVanItemBtn'
        ];
        addButtonIds.forEach(btnId => {
            const btn = document.getElementById(btnId);
            if (btn) btn.style.display = 'none';
        });
    }

    // Store permissions globally for use in render functions
    window.currentUserPermissions = permissions;

    // Render the appropriate dashboard based on user role
    renderDashboardByRole();

    if (!isOnline) {
        document.getElementById('offlineBadge').classList.add('show');
    }
}

window.logout = () => {
    if (confirm('Are you sure you want to logout?')) {
        clearSession();
        currentUser = null;
        window.currentUser = null; // Clear from global scope
        document.getElementById('mainApp').classList.remove('active');
        document.getElementById('loginScreen').classList.remove('hidden');
        document.getElementById('loginForm').reset();
        document.getElementById('usersTabBtn').style.display = 'none';
        document.getElementById('salesTabBtn').style.display = 'none';
        showTab('dashboard');
    }
};

async function loadData() {
    try {
        console.log('🔄 Starting loadData...');
        
        // Initialize arrays if they're undefined
        if (!inventory) inventory = { warehouse: [], office: [], "service-van": [] };
        if (!projects) projects = [];
        if (!maintenance) maintenance = [];
        if (!leads) leads = [];
        if (!activities) activities = [];
        if (!employees) employees = [];
        if (!invoices) invoices = [];
        
        // Show loading indicator
        const dashboardCards = document.querySelectorAll('.dashboard-card .value');
        dashboardCards.forEach(card => {
            if (card) card.style.opacity = '0.5';
        });
        
        // Load data with individual error handling
        console.log('Loading inventory...');
        try { await loadInventory(); console.log('✅ Inventory loaded'); } catch (e) { console.error('❌ Failed to load inventory:', e); }
        
        console.log('Loading projects...');
        try { await loadProjects(); console.log('✅ Projects loaded'); } catch (e) { console.error('❌ Failed to load projects:', e); }
        
        console.log('Loading maintenance...');
        try { await loadMaintenance(); console.log('✅ Maintenance loaded'); } catch (e) { console.error('❌ Failed to load maintenance:', e); }
        
        console.log('Loading AMC...');
        try { await loadAMC(); console.log('✅ AMC loaded'); } catch (e) { console.error('❌ Failed to load AMC:', e); }

        console.log('Loading AMC Monthly Maintenance...');
        try { await loadAMCMonthlyMaintenance(); console.log('✅ AMC Monthly Maintenance loaded'); } catch (e) { console.error('❌ Failed to load AMC Monthly Maintenance:', e); }

        console.log('Loading installation activities...');
        try { await loadInstallationActivities(); console.log('✅ Installation activities loaded'); } catch (e) { console.error('❌ Failed to load installation activities:', e); }

        console.log('Loading modernisation activities...');
        try { await loadModernisationActivities(); console.log('✅ Modernisation activities loaded'); } catch (e) { console.error('❌ Failed to load modernisation activities:', e); }

        console.log('Loading repair activities...');
        try { await loadRepairActivities(); console.log('✅ Repair activities loaded'); } catch (e) { console.error('❌ Failed to load repair activities:', e); }

        console.log('Loading complaint activities...');
        try { await loadComplaintActivities(); console.log('✅ Complaint activities loaded'); } catch (e) { console.error('❌ Failed to load complaint activities:', e); }

        console.log('Loading leads...');
        try { await loadLeads(); console.log('✅ Leads loaded'); } catch (e) { console.error('❌ Failed to load leads:', e); }
        
        console.log('Loading activities...');
        try { await loadActivities(); console.log('✅ Activities loaded'); } catch (e) { console.error('❌ Failed to load activities:', e); }
        
        console.log('Loading employees...');
        try { await loadEmployees(); console.log('✅ Employees loaded'); } catch (e) { console.error('❌ Failed to load employees:', e); }
        
        console.log('Loading tasks...');
        try { await loadTasks(); console.log('✅ Tasks loaded'); } catch (e) { console.error('❌ Failed to load tasks:', e); }
        
        console.log('Loading salary slips...');
        try { await loadSalarySlips(); console.log('✅ Salary slips loaded'); } catch (e) { console.error('❌ Failed to load salary slips:', e); }
        
        console.log('Loading billing data...');
        try { await loadBillingData(); console.log('✅ Billing data loaded'); } catch (e) { console.error('❌ Failed to load billing data:', e); }
        
        console.log('Loading invoices...');
        try { await loadInvoices(); console.log('✅ Invoices loaded'); } catch (e) { console.error('❌ Failed to load invoices:', e); }
        
        console.log('Loading company settings...');
        try { await loadCompanySettings(); console.log('✅ Company settings loaded'); } catch (e) { console.error('❌ Failed to load company settings:', e); }
        
        // Hide loading indicator
        dashboardCards.forEach(card => {
            if (card) card.style.opacity = '1';
        });

        console.log('Updating dashboard...');
        renderDashboardByRole(); // Use role-based dashboard instead of admin-only

        // Delay chart rendering to ensure Chart.js is fully loaded
        setTimeout(() => {
            console.log('Rendering charts...');
            renderCharts();
        }, 500);
        
        checkLowStock();
        populateCategoryFilters();
        populateActivityUserFilter();

        // Initialize searchable dropdowns
        setTimeout(() => {
            initializeAllProjectDropdowns();
        }, 1000);

        console.log('✅ loadData completed successfully!');
    } catch (error) {
        console.error('❌ Critical error in loadData:', error);
        console.error('Error stack:', error.stack);
        // Still update dashboard with cached data
        renderDashboardByRole(); // Use role-based dashboard instead of admin-only

        // Delay chart rendering to ensure Chart.js is fully loaded
        setTimeout(() => {
            renderCharts();
        }, 500);
        checkLowStock();
        populateCategoryFilters();
        populateActivityUserFilter();

        // Initialize searchable dropdowns even on error
        setTimeout(() => {
            initializeAllProjectDropdowns();
        }, 1000);
    }
}

