        // Populate form with existing data
        document.getElementById('repairReceivedDate').value = existingActivity.receivedDate || '';
        document.getElementById('repairReceivedVia').value = existingActivity.receivedVia || 'Phone';
        document.getElementById('repairInitialDescription').value = existingActivity.initialDescription || '';

