// Custom steps for Repair
let repairCustomStepCounter = 0;
const repairStepColors = ['#ec4899', '#14b8a6', '#f97316', '#a855f7', '#06b6d4'];

window.addCustomRepairStep = (afterStep) => {
    repairCustomStepCounter++;
    const stepId = `repair-custom-step-${repairCustomStepCounter}`;
    const colorIndex = repairCustomStepCounter % repairStepColors.length;
    const stepColor = repairStepColors[colorIndex];

    const customStepHtml = `
        <div class="activity-step custom-step" id="${stepId}" data-after-step="${afterStep}" style="border-left: 3px solid ${stepColor}; padding-left: 20px; margin-bottom: 12px; position: relative; background: rgba(255,255,255,0.02); border-radius: 0 8px 8px 0;">
            <div style="position: absolute; left: -9px; top: 0; width: 15px; height: 15px; background: ${stepColor}; border-radius: 50%;"></div>
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px;">
                <input type="text" class="form-control custom-step-title" placeholder="Custom Step Title" style="font-weight: 600; background: transparent; border: 1px dashed ${stepColor}; max-width: 300px;">
                <button type="button" class="btn btn-sm" onclick="removeCustomRepairStep('${stepId}')" style="background: #ef4444; color: white; padding: 4px 8px; font-size: 11px;">✕ Remove</button>
            </div>
            <div class="form-row">
                <div class="form-group">
                    <label>Date</label>
                    <input type="date" class="form-control custom-step-date">
                </div>
                <div class="form-group">
                    <label>Status</label>
                    <select class="form-control custom-step-status">
                        <option value="Pending">Pending</option>
                        <option value="In Progress">In Progress</option>
                        <option value="Completed">Completed</option>
                    </select>
                </div>
            </div>
            <div class="form-group">
                <label>Notes</label>
                <textarea class="form-control custom-step-notes" rows="2" placeholder="Details for this step"></textarea>
            </div>
        </div>
    `;

    // Find the button after the specified step and insert before it
    const buttons = document.querySelectorAll('#repairStepsContainer button[onclick^="addCustomRepairStep"]');
    let targetButton = null;
    buttons.forEach(btn => {
        if (btn.getAttribute('onclick').includes(`(${afterStep})`)) {
            targetButton = btn;
        }
    });

    if (targetButton) {
        targetButton.insertAdjacentHTML('afterend', customStepHtml);
    }
};

window.removeCustomRepairStep = (stepId) => {
    const step = document.getElementById(stepId);
    if (step) {
        step.remove();
    }
};

function getCustomRepairStepsData() {
    const customSteps = [];
    document.querySelectorAll('#repairStepsContainer .custom-step').forEach(step => {
        customSteps.push({
            id: step.id,
            afterStep: step.dataset.afterStep,
            title: step.querySelector('.custom-step-title').value,
            date: step.querySelector('.custom-step-date').value,
            status: step.querySelector('.custom-step-status').value,
            notes: step.querySelector('.custom-step-notes').value
        });
    });
    return customSteps;
}

function loadCustomRepairSteps(customSteps) {
    // Clear existing custom steps first
    document.querySelectorAll('#repairStepsContainer .custom-step').forEach(el => el.remove());

    customSteps.forEach(step => {
        window.addCustomRepairStep(step.afterStep);
        const stepElement = document.querySelector('#repairStepsContainer .custom-step:last-of-type');
        if (stepElement) {
            stepElement.querySelector('.custom-step-title').value = step.title || '';
            stepElement.querySelector('.custom-step-date').value = step.date || '';
            stepElement.querySelector('.custom-step-status').value = step.status || 'Pending';
            stepElement.querySelector('.custom-step-notes').value = step.notes || '';
        }
    });
}

function renderRepairActivityHistory(history) {
    const container = document.getElementById('repairActivityHistoryList');
    if (!container) return;

    if (!history || history.length === 0) {
        container.innerHTML = '<div style="text-align: center; padding: 20px; color: var(--text-tertiary);">No activity history yet. Save to create first entry.</div>';
        return;
    }

    container.innerHTML = history.slice().reverse().map(entry => `
        <div style="padding: 12px; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between; align-items: flex-start;">
            <div>
                <strong style="color: var(--text-primary);">${entry.action}</strong>
                <p style="margin: 4px 0 0 0; font-size: 13px; color: var(--text-secondary);">${entry.changes || ''}</p>
            </div>
            <div style="text-align: right; font-size: 12px; color: var(--text-tertiary);">
                <div>${new Date(entry.date).toLocaleDateString()}</div>
                <div>${entry.updatedBy || entry.createdBy || 'System'}</div>
            </div>
        </div>
    `).join('');
}

// Save Repair Activity
window.saveRepairActivity = async () => {
    const maintenanceId = document.getElementById('activityRepairId').value;
    if (!maintenanceId) {
        alert('No repair record selected');
        return;
    }

    const activityData = {
        maintenanceId,
        receivedDate: document.getElementById('repairReceivedDate').value,
        receivedVia: document.getElementById('repairReceivedVia').value,
        initialDescription: document.getElementById('repairInitialDescription').value,
        diagnosisDate: document.getElementById('repairDiagnosisDate').value,
        diagnosisStatus: document.getElementById('repairDiagnosisStatus').value,
        rootCause: document.getElementById('repairRootCause').value,
        diagnosisNotes: document.getElementById('repairDiagnosisNotes').value,
        partsRequired: document.getElementById('repairPartsRequired').value,
        partsDeliveryDate: document.getElementById('repairPartsDeliveryDate').value,
        partsList: document.getElementById('repairPartsList').value,
        estimatedCost: document.getElementById('repairEstimatedCost').value,
        clientApproval: document.getElementById('repairClientApproval').value,
        startDate: document.getElementById('repairStartDate').value,
        completionDate: document.getElementById('repairCompletionDate').value,
        workStatus: document.getElementById('repairWorkStatus').value,
        finalCost: document.getElementById('repairFinalCost').value,
        workSummary: document.getElementById('repairWorkSummary').value,
        clientFeedback: document.getElementById('repairClientFeedback').value,
        customSteps: getCustomRepairStepsData(),
        updatedAt: new Date().toISOString()
    };

    try {
        const existingActivity = repairActivities.find(a => a.maintenanceId === maintenanceId);

        if (existingActivity) {
            // Update existing
            const history = existingActivity.history || [];
            history.push({
                date: new Date().toISOString(),
                action: 'Activity Updated',
                updatedBy: currentUser?.username || 'System',
                changes: 'Repair activity timeline updated'
            });
            activityData.history = history;

            await db.collection('repairActivities').doc(existingActivity.id).update(activityData);
            const index = repairActivities.findIndex(a => a.id === existingActivity.id);
            if (index !== -1) {
                repairActivities[index] = { ...repairActivities[index], ...activityData };
            }
        } else {
            // Create new
            activityData.createdAt = new Date().toISOString();
            activityData.createdBy = currentUser?.username || 'System';
            activityData.history = [{
                date: new Date().toISOString(),
                action: 'Activity Created',
                createdBy: currentUser?.username || 'System',
                changes: 'Repair activity timeline started'
            }];

            const docRef = await db.collection('repairActivities').add(activityData);
            repairActivities.push({ id: docRef.id, ...activityData });
        }

        alert('Repair activity saved successfully!');
        renderRepairActivityHistory(activityData.history);
    } catch (error) {
        console.error('Error saving repair activity:', error);
        alert('Error saving repair activity. Please try again.');
    }
};

