        doc.setFontSize(12);
        doc.setTextColor(37, 99, 235);
        doc.text('Earnings', 20, y);
        y += 8;
        
        doc.setFontSize(10);
        doc.setTextColor(0, 0, 0);
        doc.text(`Basic Salary:`, 25, y);
        doc.text(`Rs. ${parseFloat(slip.basicSalary || 0).toLocaleString()}`, 150, y);
