    document.getElementById('piClientAddress').value = quot.clientAddress || '';
    document.getElementById('piDiscountPercent').value = quot.discountPercent || 0;
    document.getElementById('piGSTPercent').value = quot.gstPercent || 18;
    
    // Populate items
