function renderFilteredQuotations(filtered) {
    const tbody = document.getElementById('quotationsList');
    if (filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" class="empty-state"><div class="empty-state-icon">🔍</div><p>No quotations match your filters.</p></td></tr>';
        return;
    }
    // Re-render with filtered data
    const temp = quotations;
    quotations = filtered;
    renderQuotations();
    quotations = temp;
}

