// Helper function for status colors
function getStatusColor(status) {
    const colors = {
        'Draft': 'secondary',
        'Sent': 'primary',
        'Accepted': 'success',
        'Rejected': 'danger',
        'Pending': 'warning',
        'Partial': 'info',
        'Paid': 'success',
        'Overdue': 'danger'
    };
    return colors[status] || 'secondary';
}

