// Show Settings Section
window.showSettingsSection = (section) => {
    // Update tabs
    document.querySelectorAll('#settingsTab .nav-tab').forEach(tab => tab.classList.remove('active'));
    event.target.classList.add('active');

    // Update sections
    document.querySelectorAll('.settings-section').forEach(sec => sec.style.display = 'none');
    if (section === 'company') {
        document.getElementById('companySettings').style.display = 'block';
    } else if (section === 'email') {
        document.getElementById('emailSettings').style.display = 'block';
    } else if (section === 'materials') {
        document.getElementById('materialsSettings').style.display = 'block';
        loadMaterials();
    } else if (section === 'preferences') {
        document.getElementById('preferencesSettings').style.display = 'block';
        loadPreferences();
    } else if (section === 'theme') {
        document.getElementById('themeSettings').style.display = 'block';
    }
};

// Initialize settings view based on user role
window.initializeSettingsView = () => {
    const isAdmin = currentUser && (currentUser.role === 'admin' || currentUser.systemRole === 'admin');

    if (!isAdmin) {
        // For non-admin users, hide admin-only settings
        document.querySelectorAll('.admin-only-setting').forEach(element => {
            element.style.display = 'none';
        });

        // Update header for personal settings
        const headerTitle = document.getElementById('settingsHeaderTitle');
        if (headerTitle) {
            headerTitle.innerHTML = `
                <span style="display: inline-flex; align-items: center; justify-content: center; width: 44px; height: 44px; background: var(--primary); color: white; border-radius: 10px; font-size: 22px;">🎨</span>
                Personal Settings
            `;
        }

        const headerDesc = document.getElementById('settingsHeaderDesc');
        if (headerDesc) {
            headerDesc.textContent = 'Customize your color theme and display preferences';
        }

        // Show theme settings by default for non-admin users
        document.querySelectorAll('.settings-section').forEach(sec => sec.style.display = 'none');
        document.getElementById('themeSettings').style.display = 'block';

        // Make theme tab active
        document.querySelectorAll('#settingsTab .nav-tab').forEach(tab => tab.classList.remove('active'));
        const themeTab = document.getElementById('themeNavTab');
        if (themeTab) themeTab.classList.add('active');
    } else {
        // For admin users, show company settings by default
        document.querySelectorAll('.settings-section').forEach(sec => sec.style.display = 'none');
        document.getElementById('companySettings').style.display = 'block';
    }
};

