// Switch Light/Dark Mode
window.switchMode = (mode) => {
    localStorage.setItem('themeMode', mode);

    // Save per-user preference to Firestore
    if (currentUser) {
        const userThemeKey = `theme_${currentUser.username || currentUser.email}`;
        localStorage.setItem(`${userThemeKey}_mode`, mode);

        // Save to Firestore for persistence across devices
        try {
            setDoc(doc(db, 'userPreferences', currentUser.username || currentUser.email), {
                themeMode: mode,
                updatedAt: new Date().toISOString()
            }, { merge: true });
        } catch (error) {
            console.log('Theme mode saved locally only');
        }
    }

    const currentTheme = localStorage.getItem('selectedTheme') || 'standard-white';
    applyTheme(currentTheme);
    updateModeButtons();
    showToast(`✨ Switched to ${mode} mode!`, 'success');
};

// Update Mode Buttons
function updateModeButtons() {
    const mode = localStorage.getItem('themeMode') || 'light';
    const lightBtn = document.getElementById('lightModeBtn');
    const darkBtn = document.getElementById('darkModeBtn');

    if (lightBtn && darkBtn) {
        if (mode === 'light') {
            lightBtn.style.background = 'var(--primary)';
            lightBtn.style.color = 'white';
            lightBtn.style.boxShadow = '0 2px 8px rgba(0,0,0,0.2)';
            darkBtn.style.background = 'transparent';
            darkBtn.style.color = 'var(--text-secondary)';
            darkBtn.style.boxShadow = 'none';
        } else {
            darkBtn.style.background = 'var(--primary)';
            darkBtn.style.color = 'white';
            darkBtn.style.boxShadow = '0 2px 8px rgba(0,0,0,0.2)';
            lightBtn.style.background = 'transparent';
            lightBtn.style.color = 'var(--text-secondary)';
            lightBtn.style.boxShadow = 'none';
        }
    }
}

// Apply Theme Function with per-user persistence
window.applyTheme = async (themeName) => {
    const themeData = themes[themeName];
    if (!themeData) {
        console.warn(`Theme '${themeName}' not found, using default`);
        themeName = 'standard-white';
    }

    // Get current mode (light or dark)
    const mode = localStorage.getItem('themeMode') || 'light';
    const theme = themeData[mode] || themes['standard-white'][mode];

    // Apply theme variables to :root
    const root = document.documentElement;
    Object.keys(theme).forEach(variable => {
        root.style.setProperty(variable, theme[variable]);
    });

    // Update checkmarks
    document.querySelectorAll('[id^="theme-check-"]').forEach(check => {
        check.style.display = 'none';
        check.style.background = 'transparent';
        check.style.border = '2px solid var(--border)';
        check.textContent = '';
    });

    const activeCheck = document.getElementById(`theme-check-${themeName}`);
    if (activeCheck) {
        activeCheck.style.display = 'flex';
        activeCheck.style.background = '#10b981';
        activeCheck.style.border = 'none';
        activeCheck.textContent = '✓';
    }

    // Save to localStorage (global fallback)
    localStorage.setItem('selectedTheme', themeName);

    // Save per-user preference
    if (currentUser) {
        const userThemeKey = `theme_${currentUser.username || currentUser.email}`;
        localStorage.setItem(userThemeKey, themeName);

        // Save to Firestore for persistence across devices
        try {
            await setDoc(doc(db, 'userPreferences', currentUser.username || currentUser.email), {
                selectedTheme: themeName,
                themeMode: mode,
                updatedAt: new Date().toISOString()
            }, { merge: true });

            await logActivity(`Changed color theme to ${themeName.replace('-', ' ').toUpperCase()} (${mode} mode)`);
        } catch (error) {
            console.log('Theme saved locally only');
        }
    }

    // Update mode buttons
    updateModeButtons();

    // Show success message
    showToast('✨ Theme applied successfully!', 'success');
};

// Load Theme on Page Load (per-user)
async function loadSavedTheme() {
    let savedTheme = 'standard-white';
    let savedMode = 'light';

    // Try to load user-specific theme first
    if (currentUser) {
        const userThemeKey = `theme_${currentUser.username || currentUser.email}`;
        const userTheme = localStorage.getItem(userThemeKey);
        const userMode = localStorage.getItem(`${userThemeKey}_mode`);

        if (userTheme) savedTheme = userTheme;
        if (userMode) savedMode = userMode;

        // Try to load from Firestore
        try {
            const docRef = doc(db, 'userPreferences', currentUser.username || currentUser.email);
            const docSnap = await getDoc(docRef);
            if (docSnap.exists()) {
                const prefs = docSnap.data();
                if (prefs.selectedTheme) savedTheme = prefs.selectedTheme;
                if (prefs.themeMode) savedMode = prefs.themeMode;
            }
        } catch (error) {
            console.log('Loading theme from localStorage');
        }
    } else {
        // Fallback to global localStorage
        savedTheme = localStorage.getItem('selectedTheme') || 'standard-white';
        savedMode = localStorage.getItem('themeMode') || 'light';
    }

    localStorage.setItem('themeMode', savedMode);
    applyTheme(savedTheme);
}

// Initialize theme on page load
document.addEventListener('DOMContentLoaded', () => {
    loadSavedTheme();
});

// Update Email Ports based on provider
window.updateEmailPorts = () => {
    const provider = document.getElementById('emailProvider').value;
    const smtpServer = document.getElementById('smtpServer');
    const smtpPort = document.getElementById('smtpPort');
    const smtpEncryption = document.getElementById('smtpEncryption');
    
    const providers = {
        gmail: { server: 'smtp.gmail.com', port: 587, encryption: 'TLS (tries 587, 465, 25)' },
        outlook: { server: 'smtp.office365.com', port: 587, encryption: 'TLS (tries 587, 465, 25)' },
        zoho: { server: 'smtp.zoho.com', port: 587, encryption: 'TLS (tries 587, 465, 25)' },
        custom: { server: '', port: 587, encryption: 'TLS' }
    };
    
    if (providers[provider]) {
        smtpServer.value = providers[provider].server;
        smtpPort.value = providers[provider].port;
        smtpEncryption.value = providers[provider].encryption;
        
        if (provider === 'custom') {
            smtpServer.removeAttribute('readonly');
            smtpPort.removeAttribute('readonly');
        } else {
            smtpServer.setAttribute('readonly', 'readonly');
            // Make port editable for all providers
            smtpPort.removeAttribute('readonly');
        }
    }
};

